<script lang="ts">
 import { page } from '$app/state';import {goto} from '$app/navigation';import { Trash2, ArrowLeft, ShieldCheck } from 'lucide-svelte';import { Dialog } from 'bits-ui';
 import Protected from '@lib/components/Protected.svelte';import Overlay from '@lib/components/Overlay.svelte';import {user} from '@lib/session';import {api} from '@lib/api';import type {Detection,Mode} from '@lib/types';
 let data=$state<Detection|null>(null),error=$state(''),mode=$state<Mode>('both'),deleting=$state(false),confirmOpen=$state(false);
 async function load(){error='';try{data=await api(`/detections/${page.params.id}`);}catch(e){error=(e as Error).message;}}
 $effect(()=>{if($user)load();});
 async function remove(){deleting=true;try{await api(`/detections/${page.params.id}`,{method:'DELETE'});await goto('/history');}catch(e){error=(e as Error).message;}finally{deleting=false;confirmOpen=false;}}
</script>
<Protected><a href="/history" class="back-link"><ArrowLeft size={15}/>Detection history</a><div class="page-title"><div><h1>Snapshot details</h1><p>One moment. Every detected detail.</p></div><Dialog.Root bind:open={confirmOpen}><Dialog.Trigger class="btn destructive"><Trash2 size={16}/>Delete snapshot</Dialog.Trigger><Dialog.Portal><Dialog.Overlay class="dialog-backdrop"/><Dialog.Content class="dialog"><Dialog.Title class="dialog-title">Delete this snapshot?</Dialog.Title><Dialog.Description>This removes the detection from your history and schedules its private image for deletion. This cannot be undone.</Dialog.Description><div class="dialog-actions"><Dialog.Close class="btn outline">Keep snapshot</Dialog.Close><button class="btn destructive" disabled={deleting} onclick={remove}>{deleting?'Deleting…':'Delete snapshot'}</button></div></Dialog.Content></Dialog.Portal></Dialog.Root></div>{#if error}<div class="notice error">{error}<button onclick={load}>Retry</button></div>{:else if data}<div class="detection-layout"><section class="panel"><div class="panel-heading"><h2>Saved image</h2><div class="segmented">{#each ['box','mask','both'] as m}<button class:chosen={mode===m} onclick={()=>mode=m as Mode}>{m==='box'?'Boxes':m==='mask'?'Masks':'Both'}</button>{/each}</div></div><div class="detail-image"><img src={data.image_url} alt="Privately saved snapshot" width={data.width} height={data.height}/><Overlay objects={data.objects} width={data.width} height={data.height} {mode} threshold={data.confidence_threshold}/></div><div class="inference-strip"><ShieldCheck size={15}/>Private image · Overlay reconstructed without inference</div></section><div class="detection-rail"><section class="panel"><div class="panel-heading"><h2>Snapshot information</h2></div><dl class="detail-info"><div><dt>Saved on</dt><dd>{new Date(data.detected_at).toLocaleString()}</dd></div><div><dt>Source</dt><dd>{data.source_type==='camera'?'Live camera':'Image upload'}</dd></div><div><dt>Model version</dt><dd>{data.model_version}</dd></div><div><dt>Resolution</dt><dd>{data.width} × {data.height}</dd></div><div><dt>Threshold</dt><dd>{Math.round(data.confidence_threshold*100)}%</dd></div></dl></section><section class="panel"><div class="panel-heading"><h2>Detected objects</h2><span class="count-pill">{data.total_objects}</span></div><div class="panel-content">{#each data.objects as o}<div class="prediction"><span>{o.object_name}</span><strong>{(o.confidence*100).toFixed(1)}%</strong></div>{:else}<p>No objects in this snapshot.</p>{/each}</div></section><p class="field-help">These predictions were generated by your browser and are not independently verified by the server.</p></div></div>{:else}<div class="loading-state">Loading snapshot…</div>{/if}</Protected>
